#!/usr/bin/env node
// Generates all Vibranium textures programmatically (original pixel art, no
// copied assets). v2 — metal identity: the ore keeps diamond-ore-style faceted
// gem clusters (in purple), while raw chunk / ingot / blocks follow vanilla's
// iron styling. Cluster structure, shading roles, and silhouettes were derived
// from measuring vanilla textures (cluster sizes, highlight counts, row extents);
// every pixel here is generated by our own rules.
//
// Usage: node tools/gen-textures.js [--previews <dir>]  (previews = 8x upscales)

const zlib = require("node:zlib");
const fs = require("node:fs");
const path = require("node:path");

// ---------- minimal PNG encoder (RGBA, 8-bit) ----------
const CRC_TABLE = (() => {
	const t = new Int32Array(256);
	for (let n = 0; n < 256; n++) {
		let c = n;
		for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
		t[n] = c;
	}
	return t;
})();
const crc32 = (buf) => {
	let c = 0xffffffff;
	for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
	return (c ^ 0xffffffff) >>> 0;
};
function pngChunk(type, data) {
	const len = Buffer.alloc(4);
	len.writeUInt32BE(data.length);
	const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
	const crc = Buffer.alloc(4);
	crc.writeUInt32BE(crc32(body));
	return Buffer.concat([len, body, crc]);
}
function encodePng(width, height, rgba) {
	const ihdr = Buffer.alloc(13);
	ihdr.writeUInt32BE(width, 0);
	ihdr.writeUInt32BE(height, 4);
	ihdr[8] = 8;
	ihdr[9] = 6;
	const raw = Buffer.alloc(height * (1 + width * 4));
	for (let y = 0; y < height; y++) {
		raw[y * (1 + width * 4)] = 0;
		rgba.copy(raw, y * (1 + width * 4) + 1, y * width * 4, (y + 1) * width * 4);
	}
	return Buffer.concat([
		Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
		pngChunk("IHDR", ihdr),
		pngChunk("IDAT", zlib.deflateSync(raw, { level: 9 })),
		pngChunk("IEND", Buffer.alloc(0)),
	]);
}

class Img {
	constructor(w, h) {
		this.w = w;
		this.h = h;
		this.d = Buffer.alloc(w * h * 4);
	}
	set(x, y, [r, g, b, a = 255]) {
		if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
		const i = (y * this.w + x) * 4;
		this.d[i] = r;
		this.d[i + 1] = g;
		this.d[i + 2] = b;
		this.d[i + 3] = a;
	}
	get(x, y) {
		const i = (y * this.w + x) * 4;
		return [this.d[i], this.d[i + 1], this.d[i + 2], this.d[i + 3]];
	}
	save(file) {
		fs.mkdirSync(path.dirname(file), { recursive: true });
		fs.writeFileSync(file, encodePng(this.w, this.h, this.d));
		console.log(`wrote ${file}`);
	}
	upscale(factor) {
		const out = new Img(this.w * factor, this.h * factor);
		for (let y = 0; y < out.h; y++)
			for (let x = 0; x < out.w; x++) out.set(x, y, this.get(Math.floor(x / factor), Math.floor(y / factor)));
		return out;
	}
}

function mulberry32(seed) {
	let a = seed >>> 0;
	return () => {
		a |= 0;
		a = (a + 0x6d2b79f5) | 0;
		let t = Math.imul(a ^ (a >>> 15), 1 | a);
		t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	};
}
const gray = (v) => [v, v, v, 255];

// ---------- palettes ----------
// Gem-cluster palette for the ore (light-dominant, like vanilla diamond ore:
// pale body + near-white sparkles + sparse vivid/dark accents + desaturated
// blend pixels feathering into the stone).
const GEM = {
	spark: [246, 236, 255, 255], // near-white lavender glint
	light: [207, 155, 255, 255], // pale violet — the cluster BODY
	vivid: [172, 100, 240, 255], // saturated accent
	dark: [116, 60, 172, 255], // deep accent (sparse)
	blend: [156, 136, 176, 255], // desaturated purple-gray feathering
	blendDark: [116, 104, 130, 255],
};
// Polished-metal palette for ingot/block.
const METAL = {
	spark: [244, 233, 255, 255],
	high: [205, 162, 244, 255],
	body: [168, 115, 222, 255],
	shade: [126, 78, 178, 255],
	dark: [88, 48, 127, 255],
	outline: [58, 30, 88, 255],
};
// Raw-metal palette (duller than polished; high contrast like vanilla raw ores).
const RAW = {
	spark: [242, 232, 252, 255],
	light: [194, 160, 220, 255],
	mid: [146, 108, 178, 255],
	dark: [88, 56, 118, 255],
	outline: [52, 30, 74, 255],
};

// ---------- stone / deepslate bases (unchanged from v1) ----------
function rockBase(seed, base, spread, blotchShades) {
	const rng = mulberry32(seed);
	const img = new Img(16, 16);
	const shade = Array.from({ length: 16 }, () => new Array(16).fill(base));
	for (let i = 0; i < 15; i++) {
		const cx = Math.floor(rng() * 16);
		const cy = Math.floor(rng() * 16);
		const dv = Math.round((rng() - 0.5) * 2 * spread);
		const rad = 1 + Math.floor(rng() * 2);
		for (let dy = -rad; dy <= rad; dy++)
			for (let dx = -rad; dx <= rad; dx++) {
				if (Math.abs(dx) + Math.abs(dy) > rad) continue;
				shade[(cy + dy + 16) % 16][(cx + dx + 16) % 16] += dv;
			}
	}
	for (let i = 0; i < 10; i++) {
		const x = Math.floor(rng() * 16);
		const y = Math.floor(rng() * 16);
		const v = blotchShades[Math.floor(rng() * blotchShades.length)];
		shade[y][x] = v;
		if (rng() < 0.5) shade[y][(x + 1) % 16] = v;
	}
	for (let y = 0; y < 16; y++)
		for (let x = 0; x < 16; x++) {
			const v = Math.max(0, Math.min(255, shade[y][x] + Math.round((rng() - 0.5) * 10)));
			img.set(x, y, gray(v));
		}
	return img;
}

// ---------- ore gem clusters ----------
// Structure measured from vanilla diamond ore: 4-5 prominent clusters of ~5-9px
// (one larger), bodies of LIGHT tone, 1-2 near-white sparkles inside each
// larger cluster, sparse vivid/dark accents, blend-tone pixels feathering the rim.
// Cells: [dx, dy, role]. Hand-designed, tiling-safe (nothing crosses the edge).
const CLUSTERS = [
	// A: large cluster, left-center (9 gem px + feathering)
	{ x: 2, y: 4, cells: [
		[1, 0, "light"], [2, 0, "spark"],
		[0, 1, "light"], [1, 1, "spark"], [2, 1, "light"], [3, 1, "vivid"],
		[0, 2, "vivid"], [1, 2, "light"], [2, 2, "light"],
		[1, 3, "dark"],
		[3, 0, "blend"], [-1, 1, "blend"], [3, 2, "blend"], [0, 3, "blendDark"], [2, 3, "blend"],
	] },
	// B: medium cluster, top-right (6 gem px)
	{ x: 9, y: 1, cells: [
		[1, 0, "light"], [2, 0, "light"],
		[0, 1, "light"], [1, 1, "spark"], [2, 1, "vivid"],
		[1, 2, "dark"],
		[3, 1, "blend"], [0, 2, "blend"], [2, 2, "blendDark"],
	] },
	// C: medium-large cluster, bottom-right (7 gem px)
	{ x: 10, y: 9, cells: [
		[1, 0, "light"], [2, 0, "vivid"],
		[0, 1, "light"], [1, 1, "spark"], [2, 1, "light"], [3, 1, "light"],
		[2, 2, "dark"],
		[0, 0, "blend"], [4, 1, "blend"], [1, 2, "blend"], [3, 2, "blendDark"],
	] },
	// D: small cluster, bottom-left (5 gem px)
	{ x: 3, y: 11, cells: [
		[1, 0, "light"], [2, 0, "light"],
		[0, 1, "vivid"], [1, 1, "spark"],
		[1, 2, "dark"],
		[2, 1, "blend"], [0, 2, "blendDark"],
	] },
	// E: satellite pair, right edge-ish (2 gem px)
	{ x: 13, y: 5, cells: [
		[0, 0, "light"], [1, 1, "vivid"],
		[1, 0, "blend"], [0, 1, "blend"],
	] },
];
function addGemClusters(img, blendWithBase) {
	for (const cluster of CLUSTERS)
		for (const [dx, dy, role] of cluster.cells) {
			if (role === "blend" || role === "blendDark") {
				// feather: average the blend tone with the underlying rock pixel
				const base = img.get(cluster.x + dx, cluster.y + dy);
				const tone = GEM[role];
				if (blendWithBase) {
					img.set(cluster.x + dx, cluster.y + dy, [
						(base[0] + tone[0]) >> 1,
						(base[1] + tone[1]) >> 1,
						(base[2] + tone[2]) >> 1,
						255,
					]);
				} else img.set(cluster.x + dx, cluster.y + dy, tone);
			} else img.set(cluster.x + dx, cluster.y + dy, GEM[role]);
		}
	return img;
}
const vibraniumOre = () => addGemClusters(rockBase(1337, 128, 22, [96, 104, 150, 158]), true);
function deepslateVibraniumOre() {
	const img = rockBase(4242, 74, 16, [52, 58, 92]);
	const rng = mulberry32(99);
	for (let x = 0; x < 16; x++) {
		const bias = Math.round((rng() - 0.5) * 8);
		for (let y = 0; y < 16; y++) {
			const [r] = img.get(x, y);
			img.set(x, y, gray(Math.max(0, Math.min(255, r + bias))));
		}
	}
	return addGemClusters(img, true);
}

// ---------- raw_vibranium item: lumpy raw-metal chunk (raw-iron structure:
// one big irregular blob, bright top-left mass, dark bottom-right shading) ----
function rawVibranium() {
	const img = new Img(16, 16);
	// silhouette: angular chunk — flat edges, corner cuts, and a right-side
	// protrusion; deliberately NOT elliptical so it reads as rock, not a ball
	const rows = {
		1: [4, 8], 2: [3, 8], 3: [2, 11], 4: [2, 13], 5: [1, 13], 6: [1, 14],
		7: [0, 14], 8: [0, 13], 9: [1, 14], 10: [3, 13], 11: [3, 12], 12: [6, 11], 13: [8, 11],
	};
	const inside = (x, y) => rows[y] !== undefined && x >= rows[y][0] && x <= rows[y][1];
	// hard-edged dark pockets and mid facets make it read as rough ore, not a sphere
	const pockets = new Set(["9,6", "10,6", "9,7", "10,7", "5,10", "6,10", "5,11", "11,9", "12,9", "3,7", "3,8"]);
	const midFacets = new Set(["7,4", "8,4", "9,4", "8,5", "7,6", "6,6", "11,4", "12,5", "6,8", "7,8", "8,9"]);
	for (const [yStr, [x0, x1]] of Object.entries(rows)) {
		const y = Number(yStr);
		for (let x = x0; x <= x1; x++) {
			const border = !inside(x - 1, y) || !inside(x + 1, y) || !inside(x, y - 1) || !inside(x, y + 1);
			let color;
			if (border) color = RAW.outline;
			else if (pockets.has(`${x},${y}`)) color = RAW.dark;
			else if (midFacets.has(`${x},${y}`)) color = RAW.mid;
			else if (x + y >= 18 || (x >= 10 && y >= 9)) color = RAW.dark; // hard form shadow, bottom-right
			else color = x + y < 11 ? RAW.light : RAW.mid;
			img.set(x, y, color);
		}
	}
	// big FLAT highlight polygon with a hard vertical right edge at x=6 —
	// the straight facet boundary is what kills the "sphere" read
	for (let y = 2; y <= 5; y++) {
		for (let x = rows[y][0] + 1; x <= 6; x++) img.set(x, y, RAW.spark);
	}
	img.set(2, 6, RAW.spark);
	img.set(3, 6, RAW.spark);
	// small secondary glint lower-right
	for (const [x, y] of [[10, 10], [11, 10], [10, 11]]) img.set(x, y, RAW.light);
	return img;
}

// ---------- vibranium_ingot: classic isometric ingot. Silhouette row extents
// match the vanilla iron ingot (measured), shading is our own: bright top-face
// diagonal band, purple body, dark lower shading, deep outline. ----------
function vibraniumIngot() {
	const img = new Img(16, 16);
	const rows = {
		2: [10, 11], 3: [7, 12], 4: [4, 13], 5: [1, 14], 6: [0, 15], 7: [0, 15],
		8: [0, 15], 9: [0, 15], 10: [0, 14], 11: [1, 12], 12: [2, 9], 13: [3, 6],
	};
	const inside = (x, y) => rows[y] !== undefined && x >= rows[y][0] && x <= rows[y][1];
	for (const [yStr, [x0, x1]] of Object.entries(rows)) {
		const y = Number(yStr);
		for (let x = x0; x <= x1; x++) {
			const border = !inside(x - 1, y) || !inside(x + 1, y) || !inside(x, y - 1) || !inside(x, y + 1);
			let color;
			if (border) color = METAL.outline;
			else {
				const band = x + y; // diagonal bands along the bar
				if (band <= 15) color = METAL.high; // top face catches the light
				else if (band <= 18) color = METAL.body;
				else if (band <= 21) color = METAL.shade;
				else color = METAL.dark;
			}
			img.set(x, y, color);
		}
	}
	// top-edge highlight streak (upper-left rim of the top face)
	for (const [x, y] of [[10, 3], [11, 3], [8, 4], [9, 4], [5, 5], [6, 5], [7, 5], [2, 6], [3, 6], [4, 6]]) {
		img.set(x, y, METAL.spark);
	}
	// glint on the right end cap
	for (const [x, y] of [[13, 6], [14, 6], [12, 7], [13, 7]]) img.set(x, y, METAL.spark);
	// front-left edge catch-light
	for (const [x, y] of [[1, 7], [2, 8], [3, 9], [4, 10]]) img.set(x, y, METAL.high);
	return img;
}

// ---------- block_of_vibranium: polished metal block (iron-block structure:
// 1px frame, stacked bands with horizontal near-white glint runs) ----------
function blockOfVibranium() {
	const img = new Img(16, 16);
	const rng = mulberry32(31);
	for (let y = 0; y < 16; y++)
		for (let x = 0; x < 16; x++) {
			let color;
			const frame = x === 0 || y === 0 || x === 15 || y === 15;
			if (frame) {
				const corner = (x === 0 || x === 15) && (y === 0 || y === 15);
				const third = y === 3 || y === 6 || y === 9 || y === 12;
				color = corner || third ? METAL.shade : METAL.high;
			} else color = METAL.body;
			img.set(x, y, color);
		}
	// subtle horizontal sheen runs every 3rd interior row: mostly "high" tone
	// with a short near-white leading glint — reads as brushed metal, not stripes
	for (const y of [1, 4, 7, 10, 13]) {
		const len = 5 + Math.floor(rng() * 4);
		for (let x = 1; x <= len; x++) img.set(x, y, METAL.high);
		img.set(1, y, METAL.spark);
		img.set(2, y, METAL.spark);
	}
	return img;
}

// ---------- raw_vibranium_block: coarse raw-metal rubble filling the tile
// (raw-iron-block proportions: light-dominant noise, ~10% white glints,
// ~8% dark pockets, patchy at a 2-3px scale) ----------
function rawVibraniumBlock() {
	const img = new Img(16, 16);
	const rng = mulberry32(555);
	// low-frequency patch grid so tones cluster like rubble, not static
	const patch = Array.from({ length: 6 }, () => Array.from({ length: 6 }, () => rng()));
	const at = (gx, gy) => patch[((gy % 6) + 6) % 6][((gx % 6) + 6) % 6];
	for (let y = 0; y < 16; y++)
		for (let x = 0; x < 16; x++) {
			const gx = Math.floor((x / 16) * 6);
			const gy = Math.floor((y / 16) * 6);
			let v = at(gx, gy) * 0.7 + rng() * 0.3;
			let color;
			if (v > 0.9) color = RAW.spark;
			else if (v > 0.5) color = RAW.light;
			else if (v > 0.15) color = RAW.mid;
			else color = RAW.dark;
			img.set(x, y, color);
		}
	return img;
}

function icon() {
	const card = new Img(16, 16);
	for (let y = 0; y < 16; y++)
		for (let x = 0; x < 16; x++) {
			const corner = (x === 0 || x === 15) && (y === 0 || y === 15);
			if (!corner) card.set(x, y, [26, 16, 38, 255]);
		}
	const ingot = vibraniumIngot();
	for (let y = 0; y < 16; y++)
		for (let x = 0; x < 16; x++) {
			const px = ingot.get(x, y);
			if (px[3] > 0) card.set(x, y, px);
		}
	return card.upscale(8);
}

// ---------- main ----------
const ROOT = path.join(__dirname, "..");
const ASSETS = path.join(ROOT, "src/main/resources/assets/vibranium");
const outputs = {
	[path.join(ASSETS, "textures/block/vibranium_ore.png")]: vibraniumOre(),
	[path.join(ASSETS, "textures/block/deepslate_vibranium_ore.png")]: deepslateVibraniumOre(),
	[path.join(ASSETS, "textures/block/block_of_vibranium.png")]: blockOfVibranium(),
	[path.join(ASSETS, "textures/block/raw_vibranium_block.png")]: rawVibraniumBlock(),
	[path.join(ASSETS, "textures/item/raw_vibranium.png")]: rawVibranium(),
	[path.join(ASSETS, "textures/item/vibranium_ingot.png")]: vibraniumIngot(),
	[path.join(ASSETS, "icon.png")]: icon(),
};
const stale = path.join(ASSETS, "textures/item/vibranium_gem.png");
if (fs.existsSync(stale)) {
	fs.unlinkSync(stale);
	console.log("removed stale vibranium_gem.png");
}
for (const [file, img] of Object.entries(outputs)) img.save(file);

const previewIdx = process.argv.indexOf("--previews");
if (previewIdx !== -1) {
	const dir = process.argv[previewIdx + 1];
	for (const [file, img] of Object.entries(outputs)) {
		if (file.endsWith("icon.png")) continue;
		img.upscale(8).save(path.join(dir, path.basename(file)));
	}
}
